    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Read contest stats field (with exit code bootstrap)\"",
      "@@ exit = \"Bootstrapped\"",
      "",
      "pid = 0",
      "",
      "pmod = pid % 24",
      "ev_substructure_position = \\",
      "    pmod == 12 | pmod == 13 | pmod == 14 | pmod == 15 | \\",
      "    pmod == 16 | pmod == 17 ? 0 : \\",
      "    pmod == 2  | pmod == 3  | pmod == 8  | pmod == 9  | \\",
      "    pmod == 22 | pmod == 23 ? 1 : \\",
      "    pmod == 0  | pmod == 5  | pmod == 6  | pmod == 11 | \\",
      "    pmod == 19 | pmod == 21 ? 2 : 3",
      "offset = 32 + 12*ev_substructure_position + 6",
      "",
      "@@",
      "",
      "MOVS r12, #0x2a40000",
      "SBC r12, r12, #0xa10000",
      "SBC r12, r12, #0xba00",
      "SBC r12, r12, #0xad",
      "",
      "ldrh r11, [r12, {offset}]",
      "ldrh r10,  [r12, {offset+2}]",
      "",
      "strh r11, [r12, #90]",
      "strh r10, [r12, #92]",
      "",
      "ldrh r11, [r12, {offset+4}]",
      "sbc r12, r12, 0xBA",
      "strh r11, [r12, {0xBB-10}]"
    ],
