    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Change ribbons and obedience (with exit code bootstrap)\"",
      "@@ author = \"E-Sh4rk\"",
      "@@ exit = \"Bootstrapped\"",
      "",
      "inaccurate_emu = 0",
      "pid = 0",
      "tid = 0",
      "sid = 0",
      "new_ribbons = 0xFC924",
      "new_obedience = 0",
      "cur_ribbons = 0",
      "cur_obedience = 0",
      "",
      "otid = tid + (sid << 16)",
      "key = pid ^ otid",
      "cur_field = (cur_obedience << 31) | (cur_ribbons & 0x7FFFFFFF)",
      "new_field = (new_obedience << 31) | (new_ribbons & 0x7FFFFFFF)",
      "new_encoded_field = new_field ^ key",
      "",
      "pmod = pid % 24",
      "misc_substructure_position = \\",
      "    pmod == 18 | pmod == 19 | pmod == 20 | pmod == 21 | \\",
      "    pmod == 22 | pmod == 23 ? 0 : \\",
      "    pmod == 4  | pmod == 5  | pmod == 10 | pmod == 11 | \\",
      "    pmod == 16 | pmod == 17 ? 1 : \\",
      "    pmod == 1  | pmod == 3  | pmod == 7  | pmod == 9  | \\",
      "    pmod == 13 | pmod == 15 ? 2 : 3",
      "offset = 32 + 12*misc_substructure_position + 8",
      "",
      "checksum_diff = ((new_field & 0xFFFF) + (new_field >> 16)) - ((cur_field & 0xFFFF) + (cur_field >> 16))",
      "",
      "@@",
      "",
      "sbc r11, r15, #0x2940",
      "",
      "LDRH r12, [r11, {inaccurate_emu ? 0x15 : 0x13}]",
      "ADC r12, r12, {checksum_diff & 0xFFFF} ?",
      "STRH r12, [r11, {inaccurate_emu ? 0x15 : 0x13}]",
      "",
      "movs r12, {new_encoded_field} ?",
      "adc r11, r11, {offset-7} ?",
      "str r12, [r11, 0]!"
    ],
    "source": {
      "label": "Original source — EmeraldACE_web (pkmn/ChangeRibbonsObedience.txt)",
      "url": "https://github.com/E-Sh4rk/EmeraldACE_web/blob/main/files/pkmn/ChangeRibbonsObedience.txt"
    },
    "sourcePlatformValues": {
      "accurate": 0,
      "inaccurate": 1
    }
