    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Create pokemon from nothing\"",
      "@@ author = \"E-Sh4rk & Final\"",
      "@@ exit = \"CertificateFull{LANG}\"",
      "",
      "species = 0xFF",
      "inaccurate_emu = 0",
      "",
      "@@",
      "",
      "sbc r11, r15, #0x2940",
      "movs r12, #0xE200",
      "bic r12, r12, #0xFF000",
      "strh r12, [r11, {inaccurate_emu? 0x0C : 0x0A}]!",
      "mov r12, {species & 0xFFFF} ?",
      "strh r12, [r11, #10]",
      "strh r12, [r11, #14]"
    ],
