      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Teleport to any map\"",
      "@@ author = \"Sleipnir17, adapted by E-Sh4rk\"",
      "@@ exit = \"LoadMapFull{LANG}\"",
      "",
      "map_id = 0x0000",
      "",
      "@@",
      "",
      "sbc r12, lr, 0xD00",
      "adcs r12, r12, 0x3000000",
      "bic r12, r12, 0xC8000000",
      "ldr r11, [r12, 0xA6]!",
      "movs r12, {map_id} ?",
      "strh r12, [r11, 4]"
