    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Read Pokérus field\"",
      "@@ exit = \"CertificateFull{LANG}\"",
      "",
      "pid = 0",
      "",
      "pmod = pid % 24",
      "misc_substructure_position = \\",
      "    pmod == 18 | pmod == 19 | pmod == 20 | pmod == 21 | \\",
      "    pmod == 22 | pmod == 23 ? 0 : \\",
      "    pmod == 4  | pmod == 5  | pmod == 10 | pmod == 11 | \\",
      "    pmod == 16 | pmod == 17 ? 1 : \\",
      "    pmod == 1  | pmod == 3  | pmod == 7  | pmod == 9  | \\",
      "    pmod == 13 | pmod == 15 ? 2 : 3",
      "offset = 32 + 12*misc_substructure_position",
      "",
      "@@",
      "",
      "MOVS r12, #0x2a40000",
      "SBC r12, r12, #0xa10000",
      "SBC r12, r12, #0xba00",
      "SBC r12, r12, #0xad",
      "ADC r10, r12, {offset} ?",
      "",
      "ldrb r11, [r10]",
      "",
      "strh r11, [r12, #90]"
    ],
