    "requirements": [
      "A compatible Emerald ACE setup for the selected language and device.",
      "Follow every prerequisite, placement instruction, and warning in the included source comments."
    ],
    "instructions": [
      "Confirm that the published default values shown in the source are the values you want.",
      "Enter the box names exactly, including spaces and symbols, then execute with the required ACE setup."
    ],
    "troubleshooting": [
      "Check every character, the selected language, and the selected console/emulator target.",
      "If you need different parameter values, edit and compile the source in E-Sh4rk’s CodeGenerator."
    ],
    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Set up wild battle with any Pokemon\"",
      "@@ author = \"Theocatic / it-is-final / Adrichu00\"",
      "@@ exit = \"CertificateShort{LANG}\"",
      "",
      "PokemonHex = 0x00C4      @input:species",
      "PokemonLV = 25",
      "",
      "ScriptStart = (PokemonLV * 0x1000000) + (PokemonHex * 0x100) + 0xB6",
      "ScriptEnd = 0x02B70000",
      "",
      "@@",
      "",
      "sbc r12, pc, #0xB400",
      "adcs r11, pc, #0xE000",
      "bic r11, r11, #0xFC000003",
      "sbc r12, r12, #0xBA",
      "str r11, [r12]!",
      "mov r12, {ScriptStart} ?",
      "str r12, [r11]!",
      "mov r12, {ScriptEnd} ?",
      "0xE7ABCCCE"
    ],
    "source": {
      "label": "Original source — EmeraldACE_web (pkmn/StartWildBattleWithAnyPokemon.txt)",
      "url": "https://github.com/E-Sh4rk/EmeraldACE_web/blob/main/files/pkmn/StartWildBattleWithAnyPokemon.txt"
    }
