    "sourceCode": [
      "; Archive note: Follow this entry's setup and safety guidance before execution.",
      "",
      "@@ title = \"Change Flag\"",
      "@@ author = \"Adrichu00 | Final\"",
      "@@ exit = \"CertificateShort{LANG}\"",
      "",
      "flag  = 0x000",
      "value = 0",
      "inaccurate_emu = 0",
      "",
      "multi_flag = 0x0000",
      "",
      "flag_offset = (inaccurate_emu? 0xAEE4: 0xAEE6) - ((flag >> 3) & ~0x01)",
      "flag_mask   = (0x0001 << (flag & 0x0F)) | (multi_flag & 0xFFFF)",
      "",
      "@@",
      "",
      "SUB  r11, pc, {flag_offset} ?",
      "MOV  r12, {flag_mask} ?",
      "BIC  r0, r12, 0x00",
      "LDRH r12, [r11]",
      "BIC  r12, r12, r0",
      "{value? 0xE0ACC000: 0x000000FF}",
      "STRH r12, [r11]"
    ],
